UPDATE products
SET stock = stock - #{quantity},
    sold_count = sold_count + #{quantity}
WHERE id = #{id} AND status = '上架' AND stock >= #{quantity}

UPDATE products
SET stock = stock + #{quantity}
WHERE id = #{id}

UPDATE products
SET sold_count = CASE WHEN sold_count >= #{quantity} THEN sold_count - #{quantity} ELSE 0 END
WHERE id = #{id}
